	configuration: UserDeploymentConfiguration;
	constraints?: ApplicationConstraints;
	jobs?: ApplicationJobsConfig;
	affinities?: ApplicationAffinities;
	priorities?: ApplicationPriorities;
	durable_objects?: DurableObjectsConfiguration;
	scheduling_hint?: ApplicationSchedulingHint;
	active_rollout_id?: RolloutID;
	rollout_active_grace_period?: ApplicationRolloutActiveGracePeriod;
	health?: ApplicationHealth;
};
```
`ListApplications.ts` is `export type ListApplications = Array<Application>;`.

**Dash instance models (relevant to `instances`):**
- `DashApplicationInstances.ts`: `{ instances: DashApplicationInstance[]; durable_objects?: DashApplicationDurableObjectInstance[]; }`
- `DashApplicationInstance.ts`: `{ id: string; created_at: string; current_placement?: Placement; type?: DeploymentType; location: string; region?: string; app_version: number; name
