type ContainerState = "active" | "degraded" | "provisioning" | "ready";

/**
 * Derive a container application's state from its health instance counters,
 * using a fixed priority order.
 */
function deriveContainerState(health: ApplicationHealth): ContainerState {
	const { failed, starting, scheduling, active } = health.instances;
	if (failed > 0) {
		return "degraded";
	}
	if (starting > 0 || scheduling > 0) {
		return "provisioning";
	}
	if (active > 0) {
		return "active";
	}
	return "ready";
}

function colorContainerState(state: ContainerState): string {
	switch (state) {
		case "active":
			return green(state);
		case "degraded":
			return red(state);
		default:
			return state;
	}
}

function containerToJson(app: DashApplication) {
	return {
		id: app.id,
		name: app.name,
		state: deriveContainerState(app.health),
		instances: app.instances,
		image: app.image,
		version: app.version,
		updated_at: app.updated_at,
		created_at: app.created_at,
	};
}

function renderContainersTable(applications: DashApplication[]): void {
	logger.table(
