		renderContainersTable(data);
		return;
	}

	// Interactive: display one page at a time.
	const { start, stop } = spinner();
	let pageToken: string | undefined;
	let totalShown = 0;
	let stopped = false;

	do {
		start("Loading containers");
		const { data, nextPageToken } = await fetchContainersPage(
			args.perPage,
			pageToken
		);
		stop();

		if (data.length === 0 && totalShown === 0) {
			logger.log("No containers found.");
			return;
		}

		if (data.length > 0) {
			renderContainersTable(data);
			totalShown += data.length;
		}

		pageToken = nextPageToken;

		if (pageToken) {
			logger.log(
				dim(
					`Showing ${totalShown} containers. Press Enter to load ${args.perPage} more, or q/Esc to stop.`
				)
			);
			await new Promise<void>((resolve) => {
				const cleanup = onKeyPress(
					(key) => {
						if (key.name === "return") {
							cleanup();
							resolve();
						} else if (
							key.name === "escape" ||
							key.name === "q" ||
							(key.name === "c" && key.ctrl)
						) {
							cleanup();
							stopped = true;
							resolve();
						}
					},
					{ escapeCodeTimeout: 25 }
				);
			});
		}
	} while (pageToken && !stopped);
}

